class AlarmStatus(GenericEMSSIMCommand):
    """Alarmstatus command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Alarmstatus command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(AlarmStatus, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.line_to_match = None
        self._ret = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "alarm_status"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_device_id(line)
                self._parse_alarm_severity(line)
                self._parse_activity(line)
                self._parse_severity_text(line)
                self._parse_event_time(line)
                self._parse_event_type(line)
                self._parse_alarm_text(line)
                self._parse_end(line)
            except ParsingDone:
                pass
        return super(AlarmStatus, self).on_new_line(line, is_full_line)

    #    11:48:48          |       /bts-28 13-12-11 11:48:48
    _re_device_id = re.compile(r"\d+:\d+:\d+\s+\|\s+(?P<DEVICE_ID>[a-zA-Z0-9\-\/]+)\s+")

    def _parse_device_id(self, line):
        if not self.line_to_match and self._regex_helper.search_compiled(AlarmStatus._re_device_id, line):
            self._ret["DEVICE_ID"] = self._regex_helper.group("DEVICE_ID")
            self.line_to_match = "device"
            raise ParsingDone

    #    11:48:48          |**     ALARM:7665 "BASE STATION TRANSMISSION ALARM"
    _re_alarm_severity = re.compile(r'\d+:\d+:\d+\s+\|(?P<SEVERITY>\**|CLR)\s+(ALARM):(?P<ID>\d+)\s+"(?P<TEXT>.*)"')

    def _parse_alarm_severity(self, line):
        if self.line_to_match == "device" and self._regex_helper.search_compiled(AlarmStatus._re_alarm_severity, line):
            self._ret["ID"] = self._regex_helper.group("ID")
            self._ret["TEXT"] = self._regex_helper.group("TEXT")
            if self._regex_helper.group("SEVERITY") == "*":
                self._ret["SEVERITY"] = "MINOR"
            elif self._regex_helper.group("SEVERITY") == "**":
                self._ret["SEVERITY"] = "MAJOR"
            elif self._regex_helper.group("SEVERITY") == "***":
                self._ret["SEVERITY"] = "CRITICAL"
            elif self._regex_helper.group("SEVERITY") == "":
                self._ret["SEVERITY"] = "WARNING"
            elif self._regex_helper.group("SEVERITY") == "CLR":
                self._ret["SEVERITY"] = "CLEAR"
            self.line_to_match = "severity"
            raise ParsingDone

    #    11:48:48          |       ACTIVITY=SET
    _re_activity = re.compile(r"ACTIVITY=(?P<ACTIVITY>\w+)")

    def _parse_activity(self, line):
        if self.line_to_match == "severity" and self._regex_helper.search_compiled(AlarmStatus._re_activity, line):
            self._ret["ACTIVITY"] = self._regex_helper.group("ACTIVITY")
            self.line_to_match = "activity"
            raise ParsingDone

    #    11:48:48          |       SEVERITY=MAJOR
    _re_severity_text = re.compile(r"SEVERITY=(?P<SEVERITY_TXT>\w+)")

    def _parse_severity_text(self, line):
        if self.line_to_match == "activity" and self._regex_helper.search_compiled(AlarmStatus._re_severity_text, line):
            self._ret["SEVERITY_TXT"] = self._regex_helper.group("SEVERITY_TXT")
            self.line_to_match = "severity_txt"
            raise ParsingDone

    #    11:48:48          |       EVENT_TIME=13-12-11 09:06:26 SEQUENCE=532
    _re_event_time = re.compile(r"EVENT_TIME=(?P<EVENT_TIME>[\d -:]+) SEQUENCE=(?P<SEQUENCE>\d+)")

    def _parse_event_time(self, line):
        if self.line_to_match == "severity_txt" and self._regex_helper.search_compiled(AlarmStatus._re_event_time, line):
            self._ret["EVENT_TIME"] = self._regex_helper.group("EVENT_TIME")
            self._ret["SEQUENCE"] = self._regex_helper.group("SEQUENCE")
            self.line_to_match = "event_time"
            raise ParsingDone

    #    11:48:48          |       EVENT_TYPE="Communication Failure"
    _re_event_type = re.compile(r'EVENT_TYPE=\s*"(?P<EVENT_TYPE>[A-Za-z\s]+)"')

    def _parse_event_type(self, line):
        if self.line_to_match == "event_time" and self._regex_helper.search_compiled(AlarmStatus._re_event_type, line):
            self._ret["EVENT_TYPE"] = self._regex_helper.group("EVENT_TYPE")
            self.line_to_match = "event_type"
            raise ParsingDone

    #    11:48:48          |       ALARM_TEXT="NTP server is not accessible"
    _re_alarm_text = re.compile(r'ALARM_TEXT="(?P<ALARM_TEXT>.*)"')

    def _parse_alarm_text(self, line):
        if self.line_to_match == "event_type" and self._regex_helper.search_compiled(AlarmStatus._re_alarm_text, line):
            self._ret["ALARM_TEXT"] = self._regex_helper.group("ALARM_TEXT")
            self.line_to_match = "alarm_text"
            raise ParsingDone

    #    11:48:48          |#A
    _re_end = re.compile(r"#A")

    def _parse_end(self, line):
        if self.line_to_match == "alarm_text" and self._regex_helper.search_compiled(AlarmStatus._re_end, line):
            self.line_to_match = None
            if "alarm_list" not in self.current_ret:
                self.current_ret["alarm_list"] = []
            self.current_ret["alarm_list"].append(self._ret)
            self._ret = {}
            raise ParsingDone


